FOR BYOS - count the leg numbers per line ID

//count the number of legNumber as in (bet.state.bets.leg.legNumber)

IF(Bet.betTypeRef=="SGL") THEN {	
	IF(Bet.legType=="W") THEN "WN"; //Win
	IF(Bet.legType=="L") THEN "PL"; //Place
	IF(Bet.legType=="I" || Bet.legType=="S") THEN "EW"; //Eachway
} ELSE IF(Bet.betTypeRef=="BYOS") THEN {
     "SM"; //Super Multi
} ELSE IF(Bet.betTypeRef NOT IN ("SGL","BYOS)) THEN{
     "ML"; //Standard Multi
} ELSE IF(Bet.betTypeRef=="SGL" && Bet.Leg.legSort=="BB") THEN{
     "ML"; //SGM/SRM
}

IF(bet.state.bets.legType IN ("I", "S")) THEN //EachWay
{
	For WIN Leg : bet.state.bets.Leg.LegPart.price.decimal;
	For PLACE Leg : (fixedOddsPlacePriceNumerator/fixedOddsPlacePriceDenominator) + 1;
}
ELSE //Other scenarios
{
	bet.state.bets.Leg.LegPart.price.decimal;
}

