1. SGL - Bet Amount
2. EW - As per I & S scenarios
3. ML & SM - Bet amount in 1st leg

IF(Bet.betTypeRef=="SGL"){
	IF(bet.state.bets.legType == "I") THEN {//Stake equally divided between WIN & Place lines
		bet.state.bets.stake.stakePerLine;}
	ELSE IF(bet.state.bets.legType == "S") THEN {//Explicitly defined stakes for the Win and Place lines (Split-stake)  
		bet.state.bets.stake.stakeWin;//for Win leg
		bet.state.bets.stake.stakePlace;//for Place leg
	}
ELSE
	bet.state.bets.stake.amount (Original);
}
ELSE{ //ML & SM (SRM/SGM considered under Multi)
	IF(bet.state.bets.Leg.legNumber==1 && bet.state.bets.Leg.LegPart.partNumber==1)  THEN 
		bet.state.bets.stake.amount (Original);
}

